        [localRtcMember.deviceId]: {
          reactionOption: reaction1,
          expireAfter: new Date(0),
        },
      });
    });
    expect(playSound).toHaveBeenCalledWith(reaction1.name);
    expect(playSound).toHaveBeenCalledWith(reaction2.name);
  });
});

