    const dateTime = new Date();
    let wasClicked = false;
    const { getByRole } = render(
      <RaisedHandIndicator
        raisedHandTime={dateTime}
        onClick={() => (wasClicked = true)}
      />,
    );
    getByRole("button").click();
    expect(wasClicked).toBe(true);
  });
});
